int sampleRateHz = 16000;
int bitsPerSample = 16;
int channels = 1;
int blockMs = 20;
int samplesPerChannel = sampleRateHz * blockMs / 1000;
int bytesPerBlock = samplesPerChannel * (bitsPerSample / 8) * channels;
int blocksPerSecond = 1000 / blockMs;
Console.WriteLine($"samples={samplesPerChannel} bytes={bytesPerBlock} blocks/s={blocksPerSecond}");
Console.WriteLine($"rawBytes/s={bytesPerBlock * blocksPerSecond}");
